def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  mulIso from Q.mk' to K (config := {contextual := true})
    fun _ ↦ simp [h]

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  have := {contextual := true}
    (QuotientGroup.mk' H).restrict K
  /card_source (QuotientGroup.mk' H).ker_restrict K (h.mpr rfl)
